import{_ as a,c as e,o as l,ah as t}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"周易常識","description":"周易常識，整理自 App 的免費易經學習文檔。","frontmatter":{"title":"周易常識","description":"周易常識，整理自 App 的免費易經學習文檔。"},"headers":[],"relativePath":"articles/basics/index.md","filePath":"articles/basics/index.md"}'),r={name:"articles/basics/index.md"};function s(n,i,c,o,d,_){return l(),e("div",null,[...i[0]||(i[0]=[t('<h1 id="周易常識-簡要" tabindex="-1">周易常識（簡要） <a class="header-anchor" href="#周易常識-簡要" aria-label="Permalink to “周易常識（簡要）”">​</a></h1><ul><li>卦（hexagram）：六爻構成，上三爻為上卦，下三爻為下卦。</li><li>爻（line）：靜爻，陰爻（斷）/陽爻（連），用彩色線條，顏色依卦象屬性（天/地/雷/風/水/火/山/澤）而定；老陰老陽為動爻，老陰後面以叉號（×）標示，老陽後面以圓圈（○）標示。</li><li>上下卦：六十四卦皆由上下二卦構成——上三爻為「上卦」（亦稱外卦、用卦），下三爻為「下卦」（亦稱內卦、體卦）。</li><li>當位（爻位的陰陽屬性）：六爻自下而上為初、二、三、四、五、上。位性：一/三/五為陽位；二/四/上（六）為陰位。陽爻居陽位、陰爻居陰位，謂之「當位」「得位」；反之為「不當位」「不得位」。</li><li>本卦/變卦：依動爻翻變而得。解讀時本卦主「體」，變卦示「用」。</li></ul><h3 id="變卦判讀-按動爻條數" tabindex="-1">變卦判讀（按動爻條數）： <a class="header-anchor" href="#變卦判讀-按動爻條數" aria-label="Permalink to “變卦判讀（按動爻條數）：”">​</a></h3><ul><li>一爻變：以本卦該動爻之爻辭為主。</li><li>兩爻變：以本卦兩條動爻之爻辭為主，以上者為主。</li><li>三爻變：以本卦與變卦之卦辭對讀（本為「貞」/體，變為「悔」/用）。</li><li>四爻變：以變卦中兩條「不變爻」之爻辭為主，以下者為主。</li><li>五爻變：以變卦中唯一「不變爻」之爻辭為主。</li><li>六爻變：以變卦之卦辭為主；乾、坤兩卦則讀「用九」「用六」。</li><li>文本來源：本 app 收錄《周易》卦辭、爻辭與象傳的中/英版本，並提供繁簡切換。</li></ul>',4)])])}const m=a(r,[["render",s]]);export{h as __pageData,m as default};
